'paper_sources' => "SELECT DISTINCT c.field_3632 internal_id,i.field_4333 internal_name,c.field_1023 weight FROM app_entity_99 c INNER JOIN app_entity_281 i ON i.id=c.field_3632 INNER JOIN app_entity_277 m ON m.field_4280=c.field_3632 OR m.field_4278=c.id WHERE m.parent_item_id={$componentId} AND ((COALESCE(m.field_4278,0)>0 AND m.field_4278=c.id) OR (COALESCE(m.field_4278,0)=0 AND m.field_4280=c.field_3632)) AND c.field_1374=3648 AND (FIND_IN_SET('190',c.field_1019)>0 OR FIND_IN_SET('322',c.field_1019)>0)",
'papers' => "SELECT DISTINCT c.id,c.field_3632 internal_id,i.field_4333 internal_name,c.field_1020 name,c.field_1021 width,c.field_1022 height,c.field_1374 unit,c.field_1023 weight,c.field_1024 thickness,paper_stock.available_stock AS available_stock,COALESCE(paper_stock.stock_records,0) AS stock_records,COALESCE(paper_stock.invalid_stock,0) AS invalid_stock,latest_purchase.price AS price,latest_purchase.purchase_id purchase_id,latest_purchase.purchase_date purchase_date FROM app_entity_99 c LEFT JOIN (SELECT article_id,unit,price,purchase_id,purchase_date FROM (SELECT p.field_1033+0 article_id,p.field_1035 unit,p.field_1037 price,p.id purchase_id, p.date_added purchase_date,ROW_NUMBER() OVER (PARTITION BY p.field_1033+0,p.field_1035 ORDER BY p.date_added DESC,p.id DESC) purchase_rank FROM app_entity_98 p WHERE p.field_1032 IN(39,3790) AND p.field_1034>0) ranked WHERE purchase_rank=1) latest_purchase ON latest_purchase.article_id=c.id AND latest_purchase.unit=c.field_1374 LEFT JOIN (SELECT s.field_1187+0 article_id, SUM(CASE WHEN s.field_1089 IN(226,319) THEN s.field_1063 WHEN s.field_1089=225 THEN s.field_1090 WHEN s.field_1089 IN(264,318) THEN -s.field_1063 END) available_stock, COUNT(*) stock_records,SUM((CASE WHEN s.field_1089=225 THEN s.field_1090 ELSE s.field_1063 END) IS NULL) invalid_stock FROM app_entity_100 s WHERE s.field_1089 IN(226,319,225,264,318) GROUP BY s.field_1187+0) paper_stock ON paper_stock.article_id=c.id INNER JOIN app_entity_281 i ON i.id=c.field_3632 WHERE c.field_1374=3648 AND (FIND_IN_SET('190',c.field_1019)>0 OR FIND_IN_SET('322',c.field_1019)>0) AND EXISTS(SELECT 1 FROM app_entity_99 a INNER JOIN app_entity_277 m ON (COALESCE(m.field_4278,0)>0 AND m.field_4278=a.id) OR (COALESCE(m.field_4278,0)=0 AND m.field_4280=a.field_3632) WHERE m.parent_item_id={$componentId} AND a.field_1374=3648 AND (FIND_IN_SET('190',a.field_1019)>0 OR FIND_IN_SET('322',a.field_1019)>0) AND a.field_1023+0=c.field_1023+0)",
'plate_prices' => "SELECT i.id,(SELECT p.field_1037 FROM app_entity_98 p INNER JOIN app_entity_99 c ON c.id=p.field_1033 AND c.field_1374=p.field_1035 WHERE (p.field_4334=i.id OR c.field_3632=i.id) AND p.field_1032 IN(39,3790) AND p.field_1034>0 ORDER BY p.date_added DESC,p.id DESC LIMIT 1) price FROM app_entity_281 i WHERE i.id IN(984,985)",
'colors' => "SELECT id,field_4251 color FROM app_entity_278 WHERE parent_item_id={$componentId}",
