'selections' => "SELECT id,field_6101 quantity_id,field_6102 selected_quantity,field_6103 plan_id,field_6104 machine_id,field_6105 base,field_6106 details FROM app_entity_388 WHERE parent_item_id={$componentId} ORDER BY id",
